"""Library expansion (migration 003): about 130 more careers across all 15 families,
and stream options for CBSE, CISCE, state boards, NIOS, IB, Cambridge and the
after-Class-10 diploma and ITI routes.

Same shape as library.py. Interest weights are derived from the RIASEC code
(first letter strongest) so every entry is consistent; the content team tunes
them per career in /admin/careers. Salary bands, exam windows and outlooks are
seed content: verify before relying on them (sources carry status "seed").
"""
from library import FAMILIES, ex, pay, tiers

F = {i + 1: f for i, f in enumerate(FAMILIES)}
RIASEC = "RIASEC"
APT = {"n": "numerical", "v": "verbal", "a": "abstract", "s": "spatial"}
LVL = {"A": "Average", "H": "High", "V": "Very High"}
WS = {"R", "A", "P", "D"}


def weights(code: str) -> list[float]:
    """RIASEC code -> six weights: 0.9 / 0.7 / 0.55 for the code letters, 0.25 otherwise."""
    strong = [0.9, 0.7, 0.55]
    return [strong[code.index(l)] if l in code else 0.25 for l in RIASEC]


def P(level, stream, exams=(), degrees=(), t1=(), t2=(), t3=(), duration=None, alt=None, notes=None):
    return dict(level=level, stream_required=stream, exams=[ex(*e) for e in exams], degrees=list(degrees),
                institutions=tiers(list(t1), list(t2), list(t3)), duration=duration, alternative_routes=alt, notes=notes)


def K(name, fam, code, apt, ws, values, description, day, entry, band, outlook, exposure, adjacent, pathways):
    """apt "n:H,v:A" -> {"numerical": "High", "verbal": "Average"}; ws "DR" -> ["D", "R"]."""
    assert set(ws) <= WS, name
    return dict(name=name, family=F[fam], riasec_code=code, interest_weights=weights(code),
                aptitude_min={APT[k]: LVL[v] for k, v in (p.split(":") for p in apt.split(","))} if apt else {},
                workstyle_fit=list(ws), values_fit=values, description=description, day_in_life=day,
                typical_entry_paths=entry, india_salary_band=pay(*band), outlook=outlook, automation_exposure=exposure,
                adjacent_emerging=adjacent, pathways=pathways)


