ALL = list(FAMILIES)


def S(name, board, subjects, keeps_open, closes, notes):
    keeps = [F[i] for i in keeps_open] if keeps_open != "all" else ALL[:]
    return dict(name=name, board=board, subjects=subjects, keeps_open=keeps, closes=[F[i] for i in closes], notes=notes)


